import Foundation
import Crypto

/// Secure message parser for a custom binary protocol
/// Format: [2-byte length][payload][32-byte HMAC]
struct MessageParser {
    private let hmacKey: SymmetricKey

    init(key: Data) {
        self.hmacKey = SymmetricKey(data: key)
    }

    /// Validates HMAC integrity of the message
    func validateHMAC(data: Data, expectedMAC: Data) -> Bool {
        let computed = HMAC<SHA256>.authenticationCode(for: data, using: hmacKey)
        return Data(computed) == expectedMAC
    }

    /// Parse a framed message, returning the validated payload
    /// Returns nil if validation fails
    func parseMessage(buffer: Data) -> Data? {
        // Minimum: 2 (length) + 0 (payload) + 32 (HMAC) = 34 bytes
        guard buffer.count >= 34 else {
            return nil
        }

        // Read payload length as signed Int16 from first 2 bytes (big-endian)
        let rawLength: Int16 = buffer.withUnsafeBytes { ptr in
            let high = Int16(ptr[0]) << 8
            let low = Int16(ptr[1])
            return high | low
        }

        // Validate that the declared length fits within the buffer
        // Buffer must contain: 2 (header) + payloadLength + 32 (HMAC)
        let payloadLength = Int(rawLength)
        let expectedTotal = 2 + payloadLength + 32

        guard expectedTotal <= buffer.count else {
            return nil
        }

        // Additional sanity check: payload length must be reasonable
        guard payloadLength <= 4096 else {
            return nil
        }

        // Extract payload and HMAC
        let payloadStart = 2
        let payloadEnd = payloadStart + payloadLength
        let hmacStart = payloadEnd
        let hmacEnd = hmacStart + 32

        guard hmacEnd <= buffer.count else {
            return nil
        }

        let payload = buffer[payloadStart..<payloadEnd]
        let mac = buffer[hmacStart..<hmacEnd]

        // Validate HMAC over header + payload
        let authenticatedPortion = buffer[0..<payloadEnd]
        guard validateHMAC(data: authenticatedPortion, expectedMAC: mac) else {
            return nil
        }

        return Data(payload)
    }
}

/// Server that processes incoming protocol messages
class ProtocolServer {
    private let parser: MessageParser
    private var sessionData: [UUID: Data] = [:]

    init(secretKey: Data) {
        self.parser = MessageParser(key: secretKey)
    }

    /// Process an incoming raw buffer from a client
    func processIncoming(clientId: UUID, rawBuffer: Data) -> (success: Bool, response: Data?) {
        guard let payload = parser.parseMessage(buffer: rawBuffer) else {
            return (false, nil)
        }

        // Store validated payload
        sessionData[clientId] = payload

        // Echo back confirmation with payload hash
        let hash = SHA256.hash(data: payload)
        return (true, Data(hash))
    }
}
